<?php
namespace qqworld_collector\module\collect_filter; class decode_taobaoke extends filter { public function decode($clickurl) { $headers = get_headers($clickurl); $tu = str_replace('Location: ', '', $headers['5']); $eturl = urldecode($tu); $u = parse_url($eturl); $param = $u['query']; $ref = str_replace('tu=', '', $param); $ch = curl_init(); curl_setopt($ch, CURLOPT_URL, $ref); curl_setopt($ch, CURLOPT_REFERER, $tu); curl_setopt($ch, CURLOPT_HEADER, false); curl_setopt($ch, CURLOPT_NOBODY,1); curl_setopt($ch, CURLOPT_RETURNTRANSFER, 1); curl_setopt($ch, CURLOPT_FOLLOWLOCATION,true); curl_setopt($ch, CURLOPT_MAXREDIRS,2); curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, false ); curl_setopt($ch, CURLOPT_SSL_VERIFYHOST, false ); $out = curl_exec($ch); $dd = curl_getinfo($ch); curl_close($ch); $item_url = $dd['url']; $item_url = preg_replace('/^.*target=/', '', $item_url); $item_url = urldecode($item_url); $item_url = preg_replace('/(id=\d*)&.*/', '$1', $item_url); return $item_url; } public function filter($item, $args, $source_link, $html, $type, $item_args, $download_args, $mode) { $item = $this->decode($item); return $item; } } ?>